@_documentation(visibility: private)
#endif
public func FfiConverterTypeSession_lower(_ value: Session) -> UnsafeMutableRawPointer {
    return FfiConverterTypeSession.lower(value)
}




/**
 * Live validation of a recover destination (doc 08 §2.4).
 */
public struct DestinationCheck {
    /**
     * True if the destination is safe (different disk, enough space).
     */
    public var ok: Bool
    /**
     * True if the destination is on the same physical disk as the source.
     */
    public var sameDisk: Bool
    /**
     * Free bytes on the destination filesystem, if known.
     */
    public var freeBytes: UInt64?
    /**
     * True if free space is below the selected size × 1.1.
     */
    public var lowSpace: Bool
    /**
     * Human-readable reason when `ok` is false.
     */
    public var reason: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * True if the destination is safe (different disk, enough space).
         */ok: Bool, 
        /**
         * True if the destination is on the same physical disk as the source.
         */sameDisk: Bool, 
        /**
         * Free bytes on the destination filesystem, if known.
         */freeBytes: UInt64?, 
        /**
         * True if free space is below the selected size × 1.1.
         */lowSpace: Bool, 
        /**
         * Human-readable reason when `ok` is false.
         */reason: String?) {
        self.ok = ok
        self.sameDisk = sameDisk
        self.freeBytes = freeBytes
        self.lowSpace = lowSpace
        self.reason = reason
    }
}

#if compiler(>=6)
extension DestinationCheck: Sendable {}
#endif


extension DestinationCheck: Equatable, Hashable {
    public static func ==(lhs: DestinationCheck, rhs: DestinationCheck) -> Bool {
        if lhs.ok != rhs.ok {
            return false
        }
        if lhs.sameDisk != rhs.sameDisk {
            return false
        }
        if lhs.freeBytes != rhs.freeBytes {
            return false
        }
        if lhs.lowSpace != rhs.lowSpace {
            return false
        }
        if lhs.reason != rhs.reason {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(ok)
        hasher.combine(sameDisk)
        hasher.combine(freeBytes)
        hasher.combine(lowSpace)
        hasher.combine(reason)
    }
}



