 */
public struct ResultPage {
    public var total: UInt64
    public var offset: UInt32
    public var items: [ResultRecord]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(total: UInt64, offset: UInt32, items: [ResultRecord]) {
        self.total = total
        self.offset = offset
        self.items = items
    }
}

#if compiler(>=6)
extension ResultPage: Sendable {}
#endif


extension ResultPage: Equatable, Hashable {
    public static func ==(lhs: ResultPage, rhs: ResultPage) -> Bool {
        if lhs.total != rhs.total {
            return false
        }
        if lhs.offset != rhs.offset {
            return false
        }
        if lhs.items != rhs.items {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(total)
        hasher.combine(offset)
        hasher.combine(items)
    }
}



