/**
 * A single result row for the GUI (from a [`CarvedRecord`]).
 */
public struct ResultRecord {
    public var id: String
    public var engine: String
    public var sourceKind: String
    public var offset: UInt64
    public var len: UInt64
    public var format: String
    public var family: String
    public var ext: String
    public var validity: String
    public var score: UInt8
    public var blockAligned: Bool
    public var name: String?
    public var date: String?
    public var model: String?
    public var hasThumbnail: Bool
    public var path: String
    public var state: String?
    public var kind: String
    public var extents: [Extent]
    public var merged: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, engine: String, sourceKind: String, offset: UInt64, len: UInt64, format: String, family: String, ext: String, validity: String, score: UInt8, blockAligned: Bool, name: String?, date: String?, model: String?, hasThumbnail: Bool, path: String, state: String?, kind: String, extents: [Extent], merged: Bool) {
        self.id = id
        self.engine = engine
        self.sourceKind = sourceKind
        self.offset = offset
        self.len = len
        self.format = format
        self.family = family
        self.ext = ext
        self.validity = validity
        self.score = score
        self.blockAligned = blockAligned
        self.name = name
        self.date = date
        self.model = model
        self.hasThumbnail = hasThumbnail
        self.path = path
        self.state = state
        self.kind = kind
        self.extents = extents
        self.merged = merged
    }
}

