/**
 * Scan configuration (doc 08 §2.2 scan plan).
 */
public struct ScanOptions {
    /**
     * Run the metadata (named-file) pass.
     */
    public var quick: Bool
    /**
     * Run the carve (deep) pass.
     */
    public var deep: Bool
    /**
     * Restrict carve to these families (empty = all).
     */
    public var families: [String]
    /**
     * Restrict carve to these signature ids (empty = all).
     */
    public var sigIds: [String]
    /**
     * Carve block size (0 = auto).
     */
    public var blockSize: UInt32
    /**
     * Byte-granular matching in non-uniform blocks.
     */
    public var bruteForce: Bool
    /**
     * Keep Truncated/Suspect carved results.
     */
    public var keepCorrupted: Bool
    /**
     * Cap on any single carved file.
     */
    public var maxFileSize: UInt64
    /**
     * Optional byte range (start,end) to scan.
     */
    public var rangeStart: UInt64?
    public var rangeEnd: UInt64?
    /**
     * Hide allocated carved results (needs the FS bitmap).
     */
    public var unallocatedOnly: Bool
    /**
     * Checkpoint interval seconds.
     */
    public var checkpointSecs: UInt64
    /**
     * Continue an interrupted scan.
     */
    public var resume: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Run the metadata (named-file) pass.
         */quick: Bool, 
        /**
         * Run the carve (deep) pass.
         */deep: Bool, 
        /**
         * Restrict carve to these families (empty = all).
         */families: [String], 
        /**
         * Restrict carve to these signature ids (empty = all).
         */sigIds: [String], 
        /**
         * Carve block size (0 = auto).
         */blockSize: UInt32, 
        /**
         * Byte-granular matching in non-uniform blocks.
         */bruteForce: Bool, 
        /**
         * Keep Truncated/Suspect carved results.
         */keepCorrupted: Bool, 
        /**
         * Cap on any single carved file.
         */maxFileSize: UInt64, 
        /**
         * Optional byte range (start,end) to scan.
         */rangeStart: UInt64?, rangeEnd: UInt64?, 
        /**
         * Hide allocated carved results (needs the FS bitmap).
         */unallocatedOnly: Bool, 
        /**
         * Checkpoint interval seconds.
         */checkpointSecs: UInt64, 
        /**
         * Continue an interrupted scan.
         */resume: Bool) {
        self.quick = quick
        self.deep = deep
        self.families = families
        self.sigIds = sigIds
        self.blockSize = blockSize
        self.bruteForce = bruteForce
        self.keepCorrupted = keepCorrupted
        self.maxFileSize = maxFileSize
        self.rangeStart = rangeStart
        self.rangeEnd = rangeEnd
        self.unallocatedOnly = unallocatedOnly
        self.checkpointSecs = checkpointSecs
        self.resume = resume
    }
}

#if compiler(>=6)
extension ScanOptions: Sendable {}
#endif


extension ScanOptions: Equatable, Hashable {
    public static func ==(lhs: ScanOptions, rhs: ScanOptions) -> Bool {
        if lhs.quick != rhs.quick {
            return false
        }
        if lhs.deep != rhs.deep {
            return false
        }
        if lhs.families != rhs.families {
            return false
        }
        if lhs.sigIds != rhs.sigIds {
            return false
        }
        if lhs.blockSize != rhs.blockSize {
            return false
        }
        if lhs.bruteForce != rhs.bruteForce {
            return false
        }
        if lhs.keepCorrupted != rhs.keepCorrupted {
            return false
        }
        if lhs.maxFileSize != rhs.maxFileSize {
            return false
        }
        if lhs.rangeStart != rhs.rangeStart {
            return false
        }
        if lhs.rangeEnd != rhs.rangeEnd {
            return false
        }
        if lhs.unallocatedOnly != rhs.unallocatedOnly {
            return false
        }
        if lhs.checkpointSecs != rhs.checkpointSecs {
            return false
        }
        if lhs.resume != rhs.resume {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(quick)
        hasher.combine(deep)
        hasher.combine(families)
        hasher.combine(sigIds)
        hasher.combine(blockSize)
        hasher.combine(bruteForce)
        hasher.combine(keepCorrupted)
        hasher.combine(maxFileSize)
        hasher.combine(rangeStart)
        hasher.combine(rangeEnd)
        hasher.combine(unallocatedOnly)
        hasher.combine(checkpointSecs)
        hasher.combine(resume)
    }
}



