/**
 * Result of a completed scan run (returned by `Session::wait`).
 */
public struct ScanSummary {
    public var found: UInt64
    public var interrupted: Bool
    public var elapsed: Double
    public var complete: Bool
    public var vanished: Bool
    public var totalRows: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(found: UInt64, interrupted: Bool, elapsed: Double, complete: Bool, vanished: Bool, totalRows: UInt64) {
        self.found = found
        self.interrupted = interrupted
        self.elapsed = elapsed
        self.complete = complete
        self.vanished = vanished
        self.totalRows = totalRows
    }
}

