    public static func ==(lhs: ScanSummary, rhs: ScanSummary) -> Bool {
        if lhs.found != rhs.found {
            return false
        }
        if lhs.interrupted != rhs.interrupted {
            return false
        }
        if lhs.elapsed != rhs.elapsed {
            return false
        }
        if lhs.complete != rhs.complete {
            return false
        }
        if lhs.vanished != rhs.vanished {
            return false
        }
        if lhs.totalRows != rhs.totalRows {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(found)
        hasher.combine(interrupted)
        hasher.combine(elapsed)
        hasher.combine(complete)
        hasher.combine(vanished)
        hasher.combine(totalRows)
    }
}



