/**
 * One enumerated source (device / partition / volume), from a
 * [`reclaim_platform_macos::Disk`].
 */
public struct SourceSummary {
    public var bsdName: String
    public var rawNode: String
    public var wholeDisk: String
    public var size: UInt64
    public var whole: Bool
    public var removable: Bool
    public var `internal`: Bool?
    public var bus: String?
    public var model: String?
    public var volumeName: String?
    public var content: String?
    public var fsKind: String?
    public var mountPoint: String?
    public var isApfsContainer: Bool
    public var filevault: Bool?
    /**
     * SMART label (`ok` / `FAILING` / `n/a` / `—`).
     */
    public var smart: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(bsdName: String, rawNode: String, wholeDisk: String, size: UInt64, whole: Bool, removable: Bool, `internal`: Bool?, bus: String?, model: String?, volumeName: String?, content: String?, fsKind: String?, mountPoint: String?, isApfsContainer: Bool, filevault: Bool?, 
        /**
         * SMART label (`ok` / `FAILING` / `n/a` / `—`).
         */smart: String) {
        self.bsdName = bsdName
        self.rawNode = rawNode
        self.wholeDisk = wholeDisk
        self.size = size
        self.whole = whole
        self.removable = removable
        self.`internal` = `internal`
        self.bus = bus
        self.model = model
        self.volumeName = volumeName
        self.content = content
        self.fsKind = fsKind
        self.mountPoint = mountPoint
        self.isApfsContainer = isApfsContainer
        self.filevault = filevault
        self.smart = smart
    }
}

#if compiler(>=6)
extension SourceSummary: Sendable {}
#endif


extension SourceSummary: Equatable, Hashable {
    public static func ==(lhs: SourceSummary, rhs: SourceSummary) -> Bool {
        if lhs.bsdName != rhs.bsdName {
            return false
        }
        if lhs.rawNode != rhs.rawNode {
            return false
        }
        if lhs.wholeDisk != rhs.wholeDisk {
            return false
        }
        if lhs.size != rhs.size {
            return false
        }
        if lhs.whole != rhs.whole {
            return false
        }
        if lhs.removable != rhs.removable {
            return false
        }
        if lhs.`internal` != rhs.`internal` {
            return false
        }
        if lhs.bus != rhs.bus {
            return false
        }
        if lhs.model != rhs.model {
            return false
        }
        if lhs.volumeName != rhs.volumeName {
            return false
        }
        if lhs.content != rhs.content {
            return false
        }
        if lhs.fsKind != rhs.fsKind {
            return false
        }
        if lhs.mountPoint != rhs.mountPoint {
            return false
        }
        if lhs.isApfsContainer != rhs.isApfsContainer {
            return false
        }
        if lhs.filevault != rhs.filevault {
            return false
        }
        if lhs.smart != rhs.smart {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(bsdName)
        hasher.combine(rawNode)
