/**
 * Errors surfaced to Swift. Each carries a human message; the variant lets the
 * UI branch (e.g. a permission failure routes to the helper/FDA onboarding,
 * a refusal shows inline red text — doc 08 §3).
 */
public enum RcError: Swift.Error {

    
    
    /**
     * The source/session/result could not be found.
     */
    case NotFound(
        /**
         * Human-readable detail.
         */msg: String
    )
    /**
     * Reading the source needs privileges the process does not have (root /
     * Full Disk Access) — the GUI routes this to onboarding.
     */
    case Permission(
        /**
         * Human-readable detail.
         */msg: String
    )
    /**
     * A safety refusal (e.g. same-disk destination).
     */
    case Refused(
        /**
         * Human-readable detail.
         */msg: String
    )
    /**
     * Invalid arguments / usage.
     */
    case Usage(
        /**
         * Human-readable detail.
         */msg: String
    )
    /**
     * An I/O or internal error.
     */
    case Internal(
        /**
         * Human-readable detail.
         */msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRcError: FfiConverterRustBuffer {
    typealias SwiftType = RcError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RcError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Permission(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Refused(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Usage(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Internal(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RcError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Permission(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Refused(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Usage(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Internal(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


