// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * A live event delivered to the Swift [`crate::EventSink`] during a scan,
 * recover or image job (doc 08 §5). Mirrors `reclaim_session::Event` plus the
 * imaging/recover progress shapes that have no session event.
 */

public enum RcEvent {
    
    case progress(pass: String, cursor: UInt64, pct: Double, rate: UInt64
    )
    case found(id: String, engine: String, path: String, size: UInt64, score: UInt8
    )
    case volume(start: UInt64, len: UInt64, fs: String, confidence: Double
    )
    case readError(lba: UInt64
    )
    case warning(msg: String
    )
    case passComplete(pass: String
    )
    case done(found: UInt64, elapsed: Double, interrupted: Bool
    )
    case imageProgress(pass: UInt8, done: UInt64, total: UInt64, badSectors: UInt64
    )
    case recoverProgress(done: UInt64, total: UInt64, path: String
    )
}


#if compiler(>=6)
extension RcEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRcEvent: FfiConverterRustBuffer {
    typealias SwiftType = RcEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RcEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .progress(pass: try FfiConverterString.read(from: &buf), cursor: try FfiConverterUInt64.read(from: &buf), pct: try FfiConverterDouble.read(from: &buf), rate: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .found(id: try FfiConverterString.read(from: &buf), engine: try FfiConverterString.read(from: &buf), path: try FfiConverterString.read(from: &buf), size: try FfiConverterUInt64.read(from: &buf), score: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 3: return .volume(start: try FfiConverterUInt64.read(from: &buf), len: try FfiConverterUInt64.read(from: &buf), fs: try FfiConverterString.read(from: &buf), confidence: try FfiConverterDouble.read(from: &buf)
        )
        
        case 4: return .readError(lba: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 5: return .warning(msg: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .passComplete(pass: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .done(found: try FfiConverterUInt64.read(from: &buf), elapsed: try FfiConverterDouble.read(from: &buf), interrupted: try FfiConverterBool.read(from: &buf)
        )
        
        case 8: return .imageProgress(pass: try FfiConverterUInt8.read(from: &buf), done: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf), badSectors: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 9: return .recoverProgress(done: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf), path: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RcEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .progress(pass,cursor,pct,rate):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(pass, into: &buf)
            FfiConverterUInt64.write(cursor, into: &buf)
            FfiConverterDouble.write(pct, into: &buf)
            FfiConverterUInt64.write(rate, into: &buf)
            
        
        case let .found(id,engine,path,size,score):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(engine, into: &buf)
            FfiConverterString.write(path, into: &buf)
            FfiConverterUInt64.write(size, into: &buf)
            FfiConverterUInt8.write(score, into: &buf)
            
        
        case let .volume(start,len,fs,confidence):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(start, into: &buf)
            FfiConverterUInt64.write(len, into: &buf)
            FfiConverterString.write(fs, into: &buf)
            FfiConverterDouble.write(confidence, into: &buf)
            
        
        case let .readError(lba):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(lba, into: &buf)
            
        
        case let .warning(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .passComplete(pass):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(pass, into: &buf)
            
        
        case let .done(found,elapsed,interrupted):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(found, into: &buf)
            FfiConverterDouble.write(elapsed, into: &buf)
            FfiConverterBool.write(interrupted, into: &buf)
            
        
        case let .imageProgress(pass,done,total,badSectors):
            writeInt(&buf, Int32(8))
            FfiConverterUInt8.write(pass, into: &buf)
            FfiConverterUInt64.write(done, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            FfiConverterUInt64.write(badSectors, into: &buf)
            
        
        case let .recoverProgress(done,total,path):
            writeInt(&buf, Int32(9))
            FfiConverterUInt64.write(done, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            FfiConverterString.write(path, into: &buf)
            
        }
    }
}


