/**
 * A sink the GUI implements to receive live scan / recover / image events
 * (doc 08 §5 `callback interface EventSink`). Implementations must be safe to
 * call from a background thread (the Swift side hops to the main actor for UI).
 */
public protocol EventSink: AnyObject, Sendable {
    
    /**
     * Called for each event as work progresses.
     */
    func onEvent(event: RcEvent) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceEventSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceEventSink] = [UniffiVTableCallbackInterfaceEventSink(
        onEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceEventSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onEvent(
                     event: try FfiConverterTypeRcEvent_lift(event)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceEventSink.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface EventSink: handle missing in uniffiFree")
            }
        }
    )]
}

private func uniffiCallbackInitEventSink() {
    uniffi_reclaim_ffi_fn_init_callback_vtable_eventsink(UniffiCallbackInterfaceEventSink.vtable)
}

